async function pDistributeLots(days){
 await pLoad();
 const next=clone(prod),state=pConfirmedPlanState(next,prodDate,days),auto=pLotPlanWork(state,db.lots);
 state.tasks=[...state.tasks,...auto.tasks];
 const now=new Date(),today=now.toLocaleDateString('sv-SE',{timeZone:'Europe/Rome'}),time=now.toLocaleTimeString('it-IT',{timeZone:'Europe/Rome',hour:'2-digit',minute:'2-digit'});
 next.plan=PC.plan(state,prodDate,days,today,PC.minute(time));
 const noPresence=!state.overrides.length;
 if(noPresence)for(const i of next.plan.issues){if(state.tasks.some(t=>t.id===i.taskId&&t.status==='pending'))i.reason='Nessuna presenza confermata nel periodo.'}
 next.plan.lotTasks=auto.tasks;
 next.plan.lotTypes=state.types;
 next.plan.lotBlocked=auto.blocked;
 await pRpc('plan',{revision:prodRevision,data:next});
 prodTab='assigned';pDraw();
}

