 $('#prodBody').innerHTML=controls+'<div class="prod-grid">'+(rows.map(t=>pPanel(prod.machines.find(m=>m.id===t.machineId)?.name||'Macchina',`<p><b>${labels[t.status]||esc(t.status)}</b> · ${t.blocking?'Macchina ferma':'Non bloccante'}</p><p>${esc(t.description)}</p>${t.maintenance?.component?'<p>Componente: '+esc(t.maintenance.component)+(t.maintenance.errorCode?' · Errore '+esc(t.maintenance.errorCode):'')+'</p>':''}${t.maintenance?.kind?'<p>'+esc({fault:'Guasto reale',planned:'Manutenzione programmata',test:'Prova / test · escluso dalle analisi'}[t.maintenance.kind]||'')+'</p>':''}${t.maintenance?.nextDate?'<p>Prossimo controllo: <b>'+esc(t.maintenance.nextDate)+'</b></p>':''}<p>Aperto da ${esc(pMember(t.createdBy))} · ${new Date(t.createdAt).toLocaleString('it-IT')}</p>${t.archivedAt?`<p>Archiviato il ${new Date(t.archivedAt).toLocaleString('it-IT')} da ${esc(pMember(t.archivedBy))}</p>`:''}<details><summary>Storico interventi</summary>${(t.history||[]).map(h=>`<p>${new Date(h.at).toLocaleString('it-IT')} · ${esc(pMember(h.actor))} · ${labels[h.status]||esc(h.status)}<br>${esc(h.note)}</p>`).join('')}${(t.archiveEvents||[]).map(h=>`<p>${new Date(h.at).toLocaleString('it-IT')} · ${esc(pMember(h.actor))} · ${h.action==='archive'?'Archiviato':'Ripristinato nell’elenco'}</p>`).join('')}</details>`,userCan('tickets_manage')?(archived?pBtn('ticketRestore',t.id,'Ripristina nell’elenco'):pBtn('ticketEdit',t.id,'Aggiorna ticket')+(t.status==='closed'?pBtn('ticketArchive',t.id,'Archivia',true):'')):'')).join('')||`<div class="empty">${archived?'Nessun ticket archiviato.':'Nessun ticket in elenco. I ticket archiviati si trovano nello Storico.'}</div>` )+'</div>';
