async function pArchiveTicket(id,restore=false){
 if(prodBusy||!userCan('tickets_manage'))return;
 const t=prod.tickets.find(x=>x.id===id);if(!t)return;
 if(!restore&&t.status!=='closed')return notify('Archivia solo i ticket risolti definitivamente.');
 prodBusy=true;
 try{await pRpc('ticket',{revision:prodRevision,id,command:restore?'restore':'archive'});pTickets();notify(restore?'Ticket ripristinato nell’elenco.':'Ticket archiviato. Lo trovi nello Storico.');}
 catch(e){notify(pError(e));}finally{prodBusy=false}
}
