function pDayHoursFields(operator){
 const days=[1,2,3,4,5,6,0];
 const names=['Domenica','Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato'];
 return `<fieldset class="wide"><legend>Orari per giorno della settimana</legend>
 <p>Seleziona i giorni da modificare. Applicando un orario, li imposti anche come lavorativi. Le pause sono quelle indicate sotto.</p>
 <div class="prod-actions">
 ${pField('bulkDayStart','Inizio comune','','time')}
 ${pField('bulkDayEnd','Fine comune','','time')}
 <button type="button" class="btn secondary" onclick="pSelectWorkingDays(this.form)">Seleziona giorni lavorativi</button>
 <button type="button" class="btn secondary" onclick="pApplyDayHours(this.form)">Applica orario ai giorni selezionati</button>
 </div>
 <p data-bulk-hours-status role="status"></p>
 ${days.map(day=>`<div style="display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin:12px 0">
 <label class="prod-check"><input type="checkbox" name="bulkDays" value="${day}">${names[day]}</label>
 ${pField('dayStart'+day,'Inizio',operator.dayHours?.[day]?.start||'','time')}
 ${pField('dayEnd'+day,'Fine',operator.dayHours?.[day]?.end||'','time')}
 </div>`).join('')}</fieldset>`;
}
function pSelectWorkingDays(form){
 const workingDays=new Set(new FormData(form).getAll('days'));
 for(const input of form.querySelectorAll('[name="bulkDays"]'))input.checked=workingDays.has(input.value);
}
function pApplyDayHours(form){
 const selected=[...form.querySelectorAll('[name="bulkDays"]:checked')];
 const {bulkDayStart,bulkDayEnd}=form.elements;
 const status=form.querySelector('[data-bulk-hours-status]');
 if(!selected.length){status.textContent='Seleziona almeno un giorno.';return;}
 if(!bulkDayStart.value||!bulkDayEnd.value||bulkDayStart.value>=bulkDayEnd.value){
  status.textContent='Inserisci un orario di inizio e uno di fine successivo.';return;
 }
 const days=new Set(selected.map(input=>input.value));
 for(const day of days){
  form.elements['dayStart'+day].value=bulkDayStart.value;
  form.elements['dayEnd'+day].value=bulkDayEnd.value;
 }
 for(const input of form.querySelectorAll('[name="days"]'))if(days.has(input.value))input.checked=true;
 status.textContent='Orario applicato ai giorni selezionati. Premi Salva per registrarlo.';
}
