async function pCommit(next,action='save'){await pRpc(action,{revision:prodRevision,data:next});$('#modal').close();pDraw();notify('Produzione salvata su Supabase.')}
const productionOperatorDrafts=new WeakMap();
async function pSaveOperator(form,operator){
 const baseline=productionOperatorDrafts.get(form);
 function mergeOperator(){
  const next=clone(prod);
  const index=next.operators.findIndex(row=>row.id===operator.id);
  const current=next.operators[index]||null;
  if(JSON.stringify(current)!==baseline){
   throw Error('Questo turno è stato modificato nel frattempo. Gli orari che hai inserito sono ancora visibili. Riapri il turno per confrontarli con quelli salvati.');
  }
  if(!prodMembers.some(member=>member.email===operator.email))throw Error('L’account scelto non è più disponibile per la pianificazione.');
  if(next.operators.some(row=>row.id!==operator.id&&row.email===operator.email))throw Error('Operatore già configurato.');
  if(index<0)next.operators.push(operator);else next.operators[index]=operator;
  pValidate(next);
  return next;
 }
 try{await pCommit(mergeOperator());}
 catch(error){
  if(error.message!=='REVISION_CONFLICT')throw error;
  await pRpc('read');
  await pCommit(mergeOperator());
 }
}
function pNumber(f,name){let v=f.get(name);return v===null||v===''?null:Number(v)}
function pValidate(next){if(!next.stations?.length)throw Error('Mantieni almeno una postazione.');for(let t of next.types)if(!next.stations.some(s=>s.id===t.station))throw Error('Postazione utilizzata da una lavorazione: riassegnala oppure disattiva la postazione.');for(let o of next.operators)if(!next.stations.some(s=>s.id===o.station)||(o.skills||[]).some(id=>!next.stations.some(s=>s.id===id)))throw Error('Postazione collegata a un operatore: modifica prima le assegnazioni.');for(let x of next.overrides)if(!x.absent&&!next.stations.some(s=>s.id===x.station))throw Error('Postazione collegata a una variazione di turno.');let ids=new Set(next.tasks.map(t=>t.id));let visiting=new Set(),visited=new Set();function visit(id){if(visiting.has(id))throw Error('Le dipendenze delle attività formano un ciclo.');if(visited.has(id))return;visiting.add(id);let t=next.tasks.find(t=>t.id===id);for(let x of t?.dependsOn||[]){if(!ids.has(x))throw Error('Attività precedente non trovata.');visit(x)}visiting.delete(id);visited.add(id)}for(let id of ids)visit(id);for(let o of next.operators){if(!o.skills.includes(o.station))throw Error('La postazione abituale deve essere fra quelle abilitate.')}for(let x of next.overrides){let o=next.operators.find(o=>o.email===x.email);if(!o)continue;if(!x.absent&&!o.skills.includes(x.station))throw Error('Operatore non abilitato alla postazione della variazione.');let r=PC.daySlots(next,o,x.date);if(r.error)throw Error(r.error)}for(let t of next.tasks){if(t.due&&t.releaseDate&&t.due.slice(0,10)<t.releaseDate)throw Error('La consegna precede la disponibilità dell’attività.')}}
