 if(kind==='machineKinds'){obj.name=String(f.get('name')||'').trim();if(!obj.name||obj.name.length>100)throw Error('Inserisci un nome da 1 a 100 caratteri.');if(next.machineKinds.some(k=>k.id!==id&&k.name.trim().toLowerCase()===obj.name.toLowerCase()))throw Error('Esiste già un tipo macchina con questo nome.');}
 if(kind==='stations'){Object.assign(obj,{name:f.get('name').trim(),kind:f.get('kind'),active:f.get('active')==='yes'});if(!obj.name)throw Error('Inserisci il nome della postazione.');if(next.stations.some(x=>x.id!==id&&rentalNormalize(x.name)===rentalNormalize(obj.name)))throw Error('Esiste già una postazione con questo nome.');}
 if(kind==='operators'){Object.assign(obj,{email:f.get('email'),station:f.get('station'),skills:f.getAll('skills'),start:f.get('start'),end:f.get('end'),days:f.getAll('days').map(Number),active:f.get('active')==='yes',breaks:[0,1,2].map(i=>({name:['Pausa mattina','Pranzo','Pausa pomeriggio'][i],start:f.get('breakStart'+i),minutes:pNumber(f,'breakMinutes'+i)}))});obj.dayHours={};for(let d=0;d<7;d++){let start=f.get('dayStart'+d)||'',end=f.get('dayEnd'+d)||'';if(start||end){obj.dayHours[d]={start,end};if(obj.days.includes(d)){let result=PC.intervals(PC.shiftForDay(obj,d));if(result.error)throw Error(['Domenica','Lunedì','Martedì','Mercoledì','Giovedì','Venerdì','Sabato'][d]+': '+result.error);}}}if(next.operators.some(o=>o.id!==id&&o.email===obj.email))throw Error('Operatore già configurato.');}
