 if(kind==='machines'){Object.assign(obj,{name:f.get('name').trim(),kind:f.get('kind'),capacity:pNumber(f,'capacity'),start:f.get('start'),end:f.get('end'),active:f.get('active')==='yes'});if(obj.start&&obj.end&&obj.start>=obj.end)throw Error('Controlla l’orario della macchina.');}
