 if(kind==='route'){let l=db.lots.find(l=>l.id===Number(f.get('lotId'))),rows=l?.rows.filter(r=>!['Uscito','Dismesso'].includes(r.state))||[];if(!rows.length)throw Error('Il lotto non contiene prodotti da lavorare.');if(next.tasks.some(t=>t.routeLotId===l.id&&!t.routeRetired&&t.status!=='cancelled'))throw Error('Esiste già un percorso per questo lotto. Aggiungi soltanto le attività mancanti, per evitare doppioni.');let wash=f.get('washType'),dry=f.get('dryType'),due=f.get('due'),previous=[];if(rows.some(r=>r.washRequired&&!r.washed)&&!wash)throw Error('Ci sono prodotti con lavaggio richiesto non completato. Seleziona il programma o registra prima il lavaggio nel lotto.');if(rows.some(r=>r.rewash)&&!wash)throw Error('Ci sono rilavaggi: seleziona il programma di lavaggio.');if(wash&&new Set(rows.map(r=>r.processingId).filter(Boolean)).size>1)throw Error('Il lotto contiene programmi diversi. Usa Nuova attività per creare carichi separati.');let add=(typeId,rr,deps,title)=>{let t={id:pId(),typeId,quantity:rr.length,items:rr.map(r=>({lotId:l.id,code:r.code})),dependsOn:[...deps],due,releaseDate:prodDate,status:'pending',sessions:[],priority:0,assignee:null,routeLotId:l.id,title};next.tasks.push(t);return t.id};if(wash)previous=[add(wash,rows,previous,'Lavaggio · '+lotno(l))];if(dry)previous=[add(dry,rows,previous,'Asciugatura · '+lotno(l))];let folds=[],normal=rows.filter(r=>!r.repair);if(normal.length)folds.push(add('fold',normal,previous,'Controllo e piegatura · '+lotno(l)));for(let r of rows.filter(r=>r.repair)){let repair=add(f.get('repairType'),[r],previous,'Riparazione · '+r.code);folds.push(add('fold',[r],[repair],'Controllo dopo riparazione · '+r.code))}add('exit',rows,folds,'Smistamento e uscita · '+lotno(l));pValidate(next);await pCommit(next);return}
