document.addEventListener('click',e=>{let b=e.target.closest('[data-prod-action]');if(b)void pAction(b.dataset.prodAction,b.dataset.prodId)});
const renderBeforeProduction=render;render=function(){renderBeforeProduction();if(!cloudUser)return;let nav=$('#nav');if(nav&&!$('#productionNav')){let b=document.createElement('button');b.id='productionNav';b.textContent='▦  Produzione';b.className=page===productionPage?'active':'';b.onclick=()=>go(productionPage);let lots=[...nav.querySelectorAll('button')].find(x=>x.textContent.replace(/^[^A-Za-zÀ-ÿ]+/,'').trim()==='Lotti');if(lots)lots.after(b);else nav.appendChild(b)}if(page===productionPage&&!current)void productionView()};
const detailBeforeProduction=detail;detail=function(){detailBeforeProduction();if(!current||!pAdmin())return;let b=document.createElement('button');b.className='btn secondary';b.textContent='Pianifica produzione';let id=current.id;b.onclick=async()=>{try{await pLoad();pRoute(id)}catch(e){notify(pError(e))}};$('#app .heading')?.appendChild(b)};

function pStationName(id){return prod?.stations?.find(s=>s.id===id)?.name||PC.stations[id]||id||'—'}
function pStationKind(id){return prod?.stations?.find(s=>s.id===id)?.kind||id}
function pDefaultStation(kind){return prod?.stations?.find(s=>s.kind===kind&&s.active!==false)?.id||''}
function pStationOptions(current='',keep=[]){return (prod?.stations||[]).filter(s=>s.active!==false||s.id===current||keep.includes(s.id)).map(s=>[s.id,s.name+(s.active===false?' · Disattivata':'')])}
function pStations(){ $('#prodBody').innerHTML='<div class="tools">'+(pAdmin()?pBtn('stationEdit','','Nuova postazione',true):'')+'</div><div class="notice">Il nome è modificabile. La funzione operativa mantiene i controlli sui passaggi di lavorazione. Le postazioni disattivate conservano lo storico ma non ricevono nuove assegnazioni automatiche.</div><div class="prod-grid">'+prod.stations.map(s=>pPanel(s.name,`<p>${s.active!==false?'Attiva':'Disattivata'} · ${esc({...PC.stations,other:'Altre lavorazioni'}[s.kind]||s.kind)}</p><p>${prod.operators.filter(o=>o.station===s.id||(o.skills||[]).includes(s.id)).length} operatori abilitati · ${prod.types.filter(t=>t.station===s.id).length} lavorazioni</p>`,pAdmin()?pBtn('stationEdit',s.id,'Modifica')+pBtn('stationDelete',s.id,'Elimina'):'' )).join('')+'</div>'}
function pEditStation(id){let s=prod.stations.find(s=>s.id===id)||{kind:'other',active:true};pForm('Postazione di lavoro','stations',id,pField('name','Nome postazione',s.name,'text','required maxlength="120"')+pSelect('kind','Funzione operativa',Object.entries({...PC.stations,other:'Altre lavorazioni'}),s.kind,'required '+(id?'disabled':''))+pSelect('active','Stato',[['yes','Attiva'],['no','Disattivata']],s.active!==false?'yes':'no','required')+'<p class="wide">Puoi rinominare la postazione senza cambiare operatori e lavorazioni collegate. La funzione di una postazione esistente resta invariata per conservare i controlli operativi.</p>');if(id){let h=document.createElement('input');h.type='hidden';h.name='kind';h.value=s.kind;$('#productionForm').appendChild(h)}}

function pMachineProgramOptions(drying){return prod.types.filter(t=>t.active!==false&&t.mode==='machine'&&(drying?t.machineKind==='dryer':['water','decon','dry'].includes(t.machineKind))&&prod.stations.some(s=>s.id===t.station&&s.active!==false)).map(t=>[t.id,t.name+(!(Number(t.value)>0)||t.operatorMinutes==null?' · Tempi da definire':'')])}
